import assert from 'node:assert/strict';
import test from 'node:test';
import { calculateTotal } from './cart.mjs';

test('empty cart has no shipping', () => {
  assert.deepEqual(calculateTotal([]), { subtotalCents: 0, shippingCents: 0, totalCents: 0 });
});
test('quantities and shipping use integer cents', () => {
  assert.deepEqual(calculateTotal([{ priceCents: 1200, quantity: 2 }]),
    { subtotalCents: 2400, shippingCents: 500, totalCents: 2900 });
});
test('free shipping includes the exact threshold', () => {
  assert.equal(calculateTotal([{ priceCents: 5000, quantity: 1 }]).shippingCents, 0);
});
test('custom shipping is supported', () => {
  assert.equal(calculateTotal([{ priceCents: 100, quantity: 1 }],
    { shippingCents: 200, freeShippingAtCents: 1000 }).totalCents, 300);
});
test('invalid input is rejected', () => {
  for (const items of [null, {}, [{ priceCents: -1, quantity: 1 }], [{ priceCents: 1, quantity: 0 }]]) {
    assert.throws(() => calculateTotal(items), TypeError);
  }
});
test('overflow is rejected', () => {
  assert.throws(() => calculateTotal([{ priceCents: Number.MAX_SAFE_INTEGER, quantity: 2 }]), RangeError);
});
test('percentOff discounts merchandise before shipping is added', () => {
  assert.deepEqual(calculateTotal([{ priceCents: 1000, quantity: 1 }], { percentOff: 10 }),
    { subtotalCents: 1000, shippingCents: 500, totalCents: 1400 });
});
test('percentOff rounds the discounted amount once', () => {
  assert.equal(calculateTotal([{ priceCents: 999, quantity: 1 }],
    { percentOff: 33, shippingCents: 0 }).totalCents, 669);
});
test('percentOff of 0 and 100 are accepted', () => {
  assert.equal(calculateTotal([{ priceCents: 1000, quantity: 1 }], { percentOff: 0, shippingCents: 0 }).totalCents, 1000);
  assert.equal(calculateTotal([{ priceCents: 1000, quantity: 1 }], { percentOff: 100, shippingCents: 0 }).totalCents, 0);
});
test('shipping eligibility uses the original subtotal, not the discounted one', () => {
  assert.equal(calculateTotal([{ priceCents: 5000, quantity: 1 }], { percentOff: 50 }).shippingCents, 0);
});
test('invalid percentOff is rejected', () => {
  for (const percentOff of [-1, 101, NaN, Infinity, '50', null]) {
    assert.throws(() => calculateTotal([{ priceCents: 100, quantity: 1 }], { percentOff }), TypeError);
  }
});
test('percentOff is optional and preserves default behavior', () => {
  assert.deepEqual(calculateTotal([{ priceCents: 1200, quantity: 2 }]),
    { subtotalCents: 2400, shippingCents: 500, totalCents: 2900 });
});
test('items and options are not mutated', () => {
  const items = [{ priceCents: 1000, quantity: 1 }];
  const options = { percentOff: 10 };
  const frozenItems = Object.freeze([Object.freeze({ ...items[0] })]);
  const frozenOptions = Object.freeze({ ...options });
  assert.doesNotThrow(() => calculateTotal(frozenItems, frozenOptions));
});

